{
  "stops": [
    {
      "poi_id": "p1",
      "kind": "activity",
      "must_do_id": null,
      "note": "The old bridge has a little temple perched right on top, and the carvings have watched the river longer than any of us."
    },
    {
      "poi_id": "p2",
      "kind": "activity",
      "must_do_id": null,
      "note": "Incense coils hang like slow red clocks, and the Fujian carvers clearly never did anything halfway."
    },
    {
      "poi_id": "p3",
      "kind": "activity",
      "must_do_id": null,
      "note": "A merchant house that floods every few years, so the good furniture rides on pulleys and the family just shrugs."
    },
    {
      "poi_id": "p4",
      "kind": "activity",
      "must_do_id": null,
      "note": "Slippery fish, piles of herbs, ladies who can haggle in three languages before you blink."
    },
    {
      "poi_id": "p10",
      "kind": "meal",
      "must_do_id": null,
      "note": "Shredded chicken, turmeric rice, herbs, and a broth on the side. Simple, and somehow exactly right."
    },
    {
      "poi_id": "p5",
      "kind": "activity",
      "must_do_id": null,
      "note": "Lanterns stacked like candy, silk glowing in the dark, and the river full of little floating wishes."
    }
  ]
}
```

