    },
    {
      "poi_id": "p14",
      "kind": "activity",
      "must_do_id": null,
      "note": "Step inside the pink cathedral for a cool, quiet half hour and a photo that looks like a postcard."
    },
    {
      "poi_id": "p22",
      "kind": "meal",
      "must_do_id": null,
      "note": "Crispy bánh xèo, fresh herbs, roll it up and let the fish sauce do the talking. Ngon quá (so tasty)."
    },
    {
      "poi_id": "p4",
      "kind": "activity",
      "must_do_id": null,
      "note": "Wait for the dragon to breathe fire over the river. Best free show in town, and I’ve seen it from the trees."
    }
  ]
}
